193	func cmdPlanShow(dir, id string) error {
194		s, err := loadStore(dir)
195		if err != nil {
196			return err
197		}
198		p, ok := s.Plans[id]
199		if !ok {
200			return fmt.Errorf("方案标识 %q 不存在", id)
201		}
202		printPlan(p)
203		return nil
204	}
