228	func cmdCustomerAddPlan(dir, id, name, planID string) error {
229		if strings.TrimSpace(id) == "" {
230			return fmt.Errorf("客户标识不能为空")
231		}
232		if strings.TrimSpace(name) == "" {
233			return fmt.Errorf("客户名称不能为空")
234		}
235		if strings.TrimSpace(planID) == "" {
236			return fmt.Errorf("方案标识不能为空")
237		}
238	
239		s, err := loadStore(dir)
240		if err != nil {
241			return err
242		}
243		p, ok := s.Plans[planID]
244		if !ok {
245			return fmt.Errorf("方案标识 %q 不存在", planID)
246		}
247		if _, exists := s.Customers[id]; exists {
248			return fmt.Errorf("客户标识 %q 已存在，客户创建后不可修改", id)
249		}
250		s.Customers[id] = &customer{ID: id, Name: name, PlanID: planID}
251	
252		// 客户整体原子落盘；保存失败则一切不生效，该客户标识不被占用。
253		if err := s.save(); err != nil {
254			delete(s.Customers, id)
255			return err
256		}
257		fmt.Fprintf(stdout, "已登记客户 %q（%s），绑定阶梯计费方案 %q（%s），绑定不可变更\n", id, name, planID, p.Name)
258		return nil
259	}
260	
261	// settleTiered 对绑定阶梯方案的客户按 UTC 自然月累计用量分档计价并封账。
262	// recs 已按计价顺序（时间点升序、同一时间按标识字典序）排列。
263	// 月累计数量、分档金额或总额溢出时拒绝结算且不封账。
264	func settleTiered(s *state, cust *customer, month string, recs []*usageRecord) error {
265		p := s.Plans[cust.PlanID] // 载入时已校验存在
266		priced, err := tieredPrice(p.Tiers, recs)
267		if err != nil {
268			return fmt.Errorf("客户 %s 的 %s 阶梯计价失败，拒绝结算且不封账: %w", cust.ID, month, err)
269		}
270	
271		lines := make([]billLine, len(recs))
272		for i, u := range recs {
273			lines[i] = billLine{
274				UsageID:  u.ID,
275				Time:     u.Time,
276				Quantity: u.Quantity,
277				LineFee:  priced.lines[i].fee,
278				Segments: priced.lines[i].segments,
279			}
280		}
281		tierTotals := make([]tierTotal, len(p.Tiers))
282		for i := range p.Tiers {
283			tierTotals[i] = tierTotal{Quantity: priced.tierQty[i], Fee: priced.tierFee[i]}
284		}
285		// 账单保存方案标识、名称与完整规则快照，之后计价与校验只依赖账单自身。
286		tiersCopy := make([]tier, len(p.Tiers))
287		copy(tiersCopy, p.Tiers)
288		b := &bill{
289			ID:         stableBillID(cust.ID, month),
290			CustomerID: cust.ID,
291			Month:      month,
292			Pricing:    "tiered",
293			PlanID:     p.ID,
294			PlanName:   p.Name,
295			PlanTiers:  tiersCopy,
296			TierTotals: tierTotals,
297			TotalQty:   priced.totalQty,
298			TotalFee:   priced.totalFee,
299			Lines:      lines,
300			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
301		}
302		key := billKey(cust.ID, month)
303		s.Bills[key] = b
304	
305		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
306		if err := s.save(); err != nil {
307			delete(s.Bills, key)
308			return err
309		}
310		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账（阶梯计费）：\n\n", cust.ID, month)
311		printBill(b, cust, s)
312		return nil
313	}
