628	// tiersEqual 判定两份阶梯规则完全相同。
629	func tiersEqual(a, b []tier) bool {
630		if len(a) != len(b) {
631			return false
632		}
633		for i := range a {
634			if a[i] != b[i] {
635				return false
636			}
637		}
638		return true
639	}
640	
641	// segmentsEqual 判定两份分段列表完全相同。
642	func segmentsEqual(a, b []lineSegment) bool {
643		if len(a) != len(b) {
644			return false
645		}
646		for i := range a {
647			if a[i] != b[i] {
648				return false
649			}
650		}
651		return true
652	}
