205	func cmdUsageImport(dir, file string) error {
206		var reader io.ReadCloser
207		var source string
208		if file == "-" {
209			reader = io.NopCloser(os.Stdin)
210			source = "标准输入"
211		} else {
212			f, err := os.Open(file)
213			if err != nil {
214				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
215			}
216			reader = f
217			source = file
218		}
219		defer reader.Close()
220	
221		rows, parseErrs := parseUsageFile(reader)
222	
223		s, err := loadStore(dir)
224		if err != nil {
225			return err
226		}
227	
228		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
229		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
230		var problems []string
231		problems = append(problems, parseErrs...)
232	
233		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
234		var ordered []*parsedRow
235		newCount, dupCount := 0, 0
236	
237		for _, r := range rows {
238			cust, ok := s.Customers[r.rec.CustomerID]
239			if !ok {
240				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
241				continue
242			}
243			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户以单条
244			// 数量从零计价，检查分段金额不溢出（金额单位：分）。
245			if cust.PlanID == "" {
246				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
247					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
248					continue
249				}
250			} else {
251				rec := r.rec
252				if _, err := tieredPrice(s.Plans[cust.PlanID].Tiers, []*usageRecord{&rec}); err != nil {
253					problems = append(problems, fmt.Sprintf("第 %d 行：按方案 %q 对单条数量从零计价失败：%v", r.line, cust.PlanID, err))
254					continue
255				}
256			}
257	
258			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
259			var existing *usageRecord
260			if inStore, ok := s.Usage[r.rec.ID]; ok {
261				existing = inStore
262			} else if inBatch, ok := accepted[r.rec.ID]; ok {
263				existing = &inBatch.rec
264			}
265	
266			if existing != nil {
267				if !sameUsage(existing, &r.rec, r.t) {
268					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
269						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
270					continue
271				}
272				dupCount++
273				continue
274			}
275	
276			// 全新标识：不得进入该客户已封账的 UTC 自然月。
277			month := r.t.UTC().Format("2006-01")
278			if s.sealed(r.rec.CustomerID, month) {
279				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
280					r.line, r.rec.CustomerID, month, r.rec.ID))
281				continue
282			}
283	
284			rr := r
285			accepted[r.rec.ID] = rr
286			ordered = append(ordered, rr)
287			newCount++
288		}
289	
290		if len(problems) > 0 {
291			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
292		}
293	
294		for _, r := range ordered {
295			rec := r.rec
296			s.Usage[rec.ID] = &rec
297		}
298		if err := s.save(); err != nil {
299			return err
300		}
301		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
302		return nil
303	}
