305	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
306	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
307		cr := csv.NewReader(r)
308		cr.FieldsPerRecord = 4
309		cr.TrimLeadingSpace = true
310	
311		header, err := cr.Read()
312		if err == io.EOF {
313			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
314		}
315		if err != nil {
316			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
317		}
318		for i := range header {
319			header[i] = strings.TrimSpace(header[i])
320		}
321		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
322			header[2] != "time" || header[3] != "quantity" {
323			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
324		}
325	
326		var rows []*parsedRow
327		var problems []string
328		line := 1
329		for {
330			rec, err := cr.Read()
331			if err == io.EOF {
332				break
333			}
334			line++
335			if err != nil {
336				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
337				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
338					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
339					break
340				}
341				continue
342			}
343			for i := range rec {
344				rec[i] = strings.TrimSpace(rec[i])
345			}
346	
347			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
348			if id == "" {
349				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
350				continue
351			}
352			if custID == "" {
353				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
354				continue
355			}
356			t, err := time.Parse(time.RFC3339, ts)
357			if err != nil {
358				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
359				continue
360			}
361			qty, err := strconv.ParseInt(qtyText, 10, 64)
362			if err != nil {
363				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
364				continue
365			}
366			if qty <= 0 {
367				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
368				continue
369			}
370	
371			rows = append(rows, &parsedRow{
372				line: line,
373				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
374				t:    t,
375			})
376		}
377		return rows, problems
378	}
379	
380	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
381	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
382	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
383		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
384			return false
385		}
386		et, err := time.Parse(time.RFC3339, existing.Time)
387		if err != nil {
388			return existing.Time == candidate.Time
389		}
390		return et.Equal(candidateT)
391	}
392	
393	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
394	func validMonth(m string) bool {
395		t, err := time.Parse("2006-01", m)
396		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
397			return false
398		}
399		return true
400	}
401	
402	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
403	func inMonth(rfc3339, month string) bool {
404		t, err := time.Parse(time.RFC3339, rfc3339)
405		if err != nil {
406			return false
407		}
408		return t.UTC().Format("2006-01") == month
409	}
410	
411	func cmdBillSettle(dir, customerID, month string) error {
412		if !validMonth(month) {
413			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
414		}
415		s, err := loadStore(dir)
416		if err != nil {
417			return err
418		}
419		cust, ok := s.Customers[customerID]
420		if !ok {
421			return fmt.Errorf("客户标识 %q 不存在", customerID)
422		}
423	
424		key := billKey(customerID, month)
425		if existing, ok := s.Bills[key]; ok {
426			// 幂等：同一客户同一月份重复结算，直接返回原账单，
427			// 不重新计费、不产生新账单或调整、不落盘。
428			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
429			printBill(existing, cust, s)
430			return nil
431		}
432	
433		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
434		var inMonthRecs []*usageRecord
435		for _, u := range s.Usage {
436			if u.CustomerID == customerID && inMonth(u.Time, month) {
437				inMonthRecs = append(inMonthRecs, u)
438			}
439		}
440		if len(inMonthRecs) == 0 {
441			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
442		}
443		sortByInstant(inMonthRecs)
444	
445		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
446		if cust.PlanID != "" {
447			return settleTiered(s, cust, month, inMonthRecs)
448		}
449	
450		lines := make([]billLine, 0, len(inMonthRecs))
451		var totalQty, totalFee int64
452		for _, u := range inMonthRecs {
453			lineFee, err := mul64(u.Quantity, cust.Price)
454			if err != nil {
455				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
456			}
457			totalQty, err = add64(totalQty, u.Quantity)
458			if err != nil {
459				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
460			}
461			totalFee, err = add64(totalFee, lineFee)
462			if err != nil {
463				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
464			}
465			lines = append(lines, billLine{
466				UsageID:  u.ID,
467				Time:     u.Time,
468				Quantity: u.Quantity,
469				LineFee:  lineFee,
470			})
471		}
472	
473		b := &bill{
474			ID:         stableBillID(customerID, month),
475			CustomerID: customerID,
476			Month:      month,
477			TotalQty:   totalQty,
478			UnitPrice:  cust.Price,
479			TotalFee:   totalFee,
480			Lines:      lines,
481			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
482		}
483		s.Bills[key] = b
484	
485		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
486		if err := s.save(); err != nil {
487			delete(s.Bills, key)
488			return err
489		}
490		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
491		printBill(b, cust, s)
492		return nil
493	}
