535		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
536		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
537		// 涉及该月即纳入，即使后来被更正移出。
538		pays := paymentsEverFor(s, b.CustomerID, b.Month)
539		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
540		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
541		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
542		tiered := b.Pricing == "tiered"
543		if tiered {
544			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
545			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
546			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
