571		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
572		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
573		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
574		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
575		fmt.Fprintln(stdout, "明细：")
576		for i, ln := range b.Lines {
