603	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
604	func historyEvents(adjs []*adjustment) []string {
605		type event struct {
606			seq  int64
607			text string
608		}
609		var events []event
610		for _, a := range adjs {
611			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
612				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
613			if a.Revoked {
614				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
615					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
616			}
617		}
618		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
619		out := make([]string, len(events))
620		for i, ev := range events {
621			out[i] = ev.text
622		}
623		return out
624	}
