640	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
641	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
642	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
643	// 的最新分配。
644	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
645		type event struct {
646			seq  int64
647			text string
648		}
649		var events []event
650		for _, p := range pays {
651			alloc := p.amountFor(month)
652			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
653				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
654			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
655			running := alloc
656			for _, c := range correctionsFor(s, p.ID) {
657				after := allocAmountFor(c.Allocations, month)
658				if running == 0 && after == 0 {
659					continue // 本次更正不涉及本账单
660				}
661				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
662					c.ID, c.Reason, p.ID, running, after)})
663				running = after
664			}
665			if p.Revoked {
666				// 整笔撤销取消的是撤销时的最新分配。
667				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
668					p.ID, p.RevokeReason, p.ID, p.Total, running)})
669			}
670		}
671		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
672		out := make([]string, len(events))
673		for i, ev := range events {
674			out[i] = ev.text
675		}
676		return out
677	}
