909	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
910		total, err := parsePositiveAmount(totalText)
911		if err != nil {
912			return err
913		}
914		allocs, err := parseAllocations(allocArgs)
915		if err != nil {
916			return err
917		}
918		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
919		var sum int64
920		for _, al := range allocs {
921			sum, err = add64(sum, al.Amount)
922			if err != nil {
923				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
924			}
925		}
926		if sum != total {
927			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
928		}
929		return registerPayment(dir, customerID, payID, total, note, allocs)
