962	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
963	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
964	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
965		if strings.TrimSpace(payID) == "" {
966			return fmt.Errorf("收款标识不能为空")
967		}
968		if strings.TrimSpace(note) == "" {
969			return fmt.Errorf("收款备注不能为空")
970		}
971		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
972		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
973	
974		s, err := loadStore(dir)
975		if err != nil {
976			return err
977		}
978		if _, ok := s.Customers[customerID]; !ok {
979			return fmt.Errorf("客户标识 %q 不存在", customerID)
980		}
981		for _, al := range allocs {
982			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
983				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
984			}
985		}
986	
987		if existing, ok := s.Payments[payID]; ok {
988			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
989			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
990			// 已撤销的重放仍返回已撤销状态，不恢复实收。
991			if samePaymentContent(existing, customerID, total, note, allocs) {
992				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
993				printPayment(existing, s)
994				return nil
995			}
996			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
997				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
998		}
999	
1000		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1001		for _, al := range allocs {
1002			b := s.Bills[billKey(customerID, al.Month)]
1003			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1004			if err != nil {
1005				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1006			}
1007			received, err := paymentReceived(s, customerID, al.Month)
1008			if err != nil {
1009				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1010			}
1011			if payable == 0 {
1012				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1013			}
1014			if al.Amount > payable-received {
1015				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1016					al.Amount, payable-received, customerID, al.Month, payable, received)
1017			}
1018		}
1019	
1020		p := &payment{
1021			ID:          payID,
1022			CustomerID:  customerID,
1023			Total:       total,
1024			Note:        note,
1025			Allocations: allocs,
1026			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1027		}
1028		s.NextSeq++
1029		p.Seq = s.NextSeq
1030		s.Payments[payID] = p
1031	
1032		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1033		// 一切不生效，该收款标识不被占用。
1034		if err := s.save(); err != nil {
1035			delete(s.Payments, payID)
1036			s.NextSeq--
1037			return err
1038		}
1039		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1040		printAllocationBalances(s, p, allocs)
1041		fmt.Fprintln(stdout)
1042		printPayment(p, s)
1043		return nil
1044	}
