1055	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1056	func sameAllocations(a, b []paymentAllocation) bool {
1057		if len(a) != len(b) {
1058			return false
1059		}
1060		for _, al := range b {
1061			if allocAmountFor(a, al.Month) != al.Amount {
1062				return false
1063			}
1064		}
1065		return true
1066	}
1067	
1068	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1069	func formatAllocations(allocs []paymentAllocation) string {
1070		parts := make([]string, len(allocs))
1071		for i, al := range allocs {
1072			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1073		}
1074		return strings.Join(parts, ",")
1075	}
