1088	func cmdBillUnpay(dir, payID, reason string) error {
1089		if strings.TrimSpace(payID) == "" {
1090			return fmt.Errorf("收款标识不能为空")
1091		}
1092		if strings.TrimSpace(reason) == "" {
1093			return fmt.Errorf("撤销原因不能为空")
1094		}
1095	
1096		s, err := loadStore(dir)
1097		if err != nil {
1098			return err
1099		}
1100		p, ok := s.Payments[payID]
1101		if !ok {
1102			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1103		}
1104	
1105		if p.Revoked {
1106			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1107			// 改用其他原因则拒绝。
1108			if p.RevokeReason == reason {
1109				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1110				printPayment(p, s)
1111				return nil
1112			}
1113			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1114		}
1115	
1116		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1117		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1118		// 分配、更正与撤销原因永久保留。
1119		p.Revoked = true
1120		p.RevokeReason = reason
1121		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1122		s.NextSeq++
1123		p.RevokeSeq = s.NextSeq
1124	
1125		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1126		if err := s.save(); err != nil {
1127			p.Revoked = false
1128			p.RevokeReason = ""
1129			p.RevokedAt = ""
1130			p.RevokeSeq = 0
1131			s.NextSeq--
1132			return err
1133		}
1134		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1135		printAllocationBalances(s, p, currentAllocations(s, p))
1136		fmt.Fprintln(stdout)
1137		printPayment(p, s)
1138		return nil
1139	}
