1141	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1142	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1143	// 各月应付/实收取自当前库状态。
1144	func printPayment(p *payment, s *state) {
1145		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1146		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
