1151		} else {
1152			fmt.Fprintf(stdout, "当前状态：实收中\n")
1153		}
1154		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1155		for i, al := range p.Allocations {
1156			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1157			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
