func cmdCustomerChangePlan(dir, customerID, month, planID, reason string) error {
    if !validMonth(month) {
        return fmt.Errorf("生效月份 %q 无效，必须是 YYYY-MM 形式（如 2027-01）", month)
    }
    if strings.TrimSpace(planID) == "" { return fmt.Errorf("方案标识不能为空") }
    if strings.TrimSpace(reason) == "" { return fmt.Errorf("变更原因不能为空") }

    s, err := loadStore(dir)
    ...
    cust, ok := s.Customers[customerID]
    if !ok { return fmt.Errorf("客户标识 %q 不存在", customerID) }
    if cust.PlanID == "" {
        return fmt.Errorf("客户 %s 是固定单价客户，未绑定阶梯方案，不能登记方案变更", customerID)
    }
    p, ok := s.Plans[planID]
    if !ok { return fmt.Errorf("方案标识 %q 不存在", planID) }

    key := changeKey(customerID, month)
    if existing, ok := s.PlanChanges[key]; ok {
        if existing.PlanID == planID && existing.Reason == reason {
            fmt.Fprintf(stdout, "客户 %s 的 %s 方案变更已存在且内容相同，返回原记录（幂等，不重复生效）：\n\n", customerID, month)
            printPlanChange(existing, s)
            return nil
        }
        return fmt.Errorf("客户 %s 的 %s 已登记方案变更（目标方案 %q，原因 %q），内容不同，拒绝改写；已有变更不可修改",
            customerID, month, existing.PlanID, existing.Reason)
    }

    // 只能按生效月递增追加
    var maxChange string
    for _, ch := range s.PlanChanges {
        if ch.CustomerID == customerID && ch.Month > maxChange { maxChange = ch.Month }
    }
    if maxChange != "" && month <= maxChange {
        return fmt.Errorf("客户 %s 已存在生效月 %s 的方案变更，新变更生效月 %s 必须更晚（只能递增追加）", customerID, maxChange, month)
    }

    // 生效月须晚于所有已封账月份
    var maxSealed string
    for _, b := range s.Bills {
        if b.CustomerID == customerID && b.Month > maxSealed { maxSealed = b.Month }
    }
    if maxSealed != "" && month <= maxSealed {
        return fmt.Errorf("客户 %s 的 %s 已封账，新变更生效月 %s 必须晚于所有已封账月份", customerID, maxSealed, month)
    }

    // 对生效月起已导入的未封账用量按新方案逐条从零计价预检
    for _, u := range s.Usage {
        if u.CustomerID != customerID { continue }
        m := recordMonth(u.Time)  // UTC month
